#include <iostream>
#include <string>

int main() {
    std::string inp;
    std::getline(std::cin, inp);
    std::string segment = inp.substr(1, inp.size() - 2);
    size_t length_seg = segment.length();
    std::string result_str(1, inp[0]);
    size_t pos = 0;
    bool found_at_char = false;

    while (pos < length_seg) {
        if (pos + 3 <= length_seg) {
            if (segment.substr(pos, 3) == "dot") {
                result_str += ".";
                pos += 3;
                continue;
            }
        }
        if (pos + 2 <= length_seg && !found_at_char) {
            if (segment.substr(pos, 2) == "at") {
                result_str += "@";
                found_at_char = true;
                pos += 2;
                continue;
            }
        }
        result_str += segment[pos];
        ++pos;
    }
    result_str += inp.back();
    std::cout << result_str << std::endl;
    return 0;
}
